            actions: ("answer" | "approve" | "reject" | "reply" | "approve_continue" | "restart" | "rebind" | "open_session" | "open_room" | "open_work" | "open_runtimes" | "open_workdirs" | "delete_workdir")[];
            /** Format: date-time */
            read_at: string | null;
